#!/usr/bin/env python3
"""Build both static language pages from the actual app catalog; no network or analytics."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent
catalog=json.loads((R/'docs/assets/catalog.json').read_text())
features=[
('compress','Compress','Sıkıştır','Image, video, audio and PDF compression. Choose quality, reduction percentage or target size where supported. An unreachable target returns an explanation rather than silently losing features.','Görsel, video, ses ve PDF sıkıştırma. Desteklenen türlerde kalite, küçültme oranı veya hedef boyut seçilir; ulaşılamayan hedefler açıklanır.'),
('removeMetadata','Metadata','Metadata','Inspect, edit or remove supported image, PDF and media metadata, including track and chapter fields. Export a new copy.','Desteklenen görsel, PDF ve medya metadatasını incele, düzenle veya kaldır. Track/chapter alanları dahil; yeni kopya oluşturulur.'),
('editImage','Edit image','Görsel düzenle','Resize, rotate, flip and tune brightness, contrast and saturation, with an original/result preview.','Boyutlandır, döndür, yansıt; parlaklık, kontrast ve doygunluğu önizleyerek ayarla.'),
('annotateImage','Annotate','İşaretle','Independent freehand/marker and shape tools, text, arrows and Select / Move. Drawing tools no longer paint at the same time.','Bağımsız serbest çizim/marker ve şekiller, metin, oklar ve Select / Move. Her çizim aracı tek başına çalışır.'),
('frameImage','Frame image','Çerçeve ekle','Create a polished image frame with configurable padding, background, corners and shadow.','Kenar boşluğu, arka plan, köşe ve gölge ayarlarıyla görsel çerçevesi oluştur.'),
('cropImage','Crop image','Görseli kırp','Drag to select, move or resize the crop. Hold Shift to lock its ratio; Return exports a cropped copy.','Sürükleyerek alan seç, taşı veya boyutlandır. Shift oranı kilitler; Enter kırpılmış kopyayı kaydeder.'),
('normalizeAudio','Normalize audio','Ses seviyesini eşitle','Analyze loudness, then export with integrated-loudness, loudness-range and true-peak targets.','Önce ses yüksekliği analiz edilir; hedef loudness, aralık ve true-peak değerleriyle kopya kaydedilir.'),
('muteVideo','Remove audio','Video sesini kaldır','Create a silent video copy while keeping the video stream.','Video akışını koruyarak sessiz bir kopya oluştur.'),
('trimVideo','Trim video','Video kırp','Preview, drag In/Out handles, move the selection and export its range. Keyboard playback, seeking and I/O marks help refine cuts.','Önizle, In/Out tutamaçlarını sürükle, seçimi taşı ve aralığı dışa aktar. Klavyeyle oynatma, gezinme ve I/O kesimi kolaylaştırır.'),
('splitPDF','Split PDF','PDF böl','Split selected pages into individual files or groups. Specify page ranges and pages per file.','Sayfa aralıklarını ve dosya başına sayfa sayısını seçerek PDF’yi tek tek veya gruplar halinde böl.'),
('organizePDF','Organize PDF','PDF düzenle','Reorder, remove and rotate pages. Optional uniform-width output is limited when document features cannot be safely preserved.','Sayfaları sırala, çıkar ve döndür. Eşit genişlik seçeneği, belge özelliklerinin güvenle korunabildiği dosyalarda kullanılır.'),
('extractArchive','Extract archives','Arşiv aç','Extract ZIP, TAR, GZIP and RAR into a new folder. Path and link validation keeps entries inside that folder.','ZIP, TAR, GZIP ve RAR arşivlerini yeni klasöre çıkar. Yol ve link denetimleri klasör dışına yazmayı engeller.'),
('createPDF','Images to PDF','Görsellerden PDF','Combine selected images into a new PDF in the chosen order.','Seçili görselleri istenen sırayla yeni bir PDF’de birleştir.'),
('mergePDF','Merge PDFs','PDF birleştir','Combine several PDFs while preserving supported page content and navigation. Originals remain unchanged.','Birden fazla PDF’yi desteklenen sayfa içeriği ve gezinme özellikleri korunarak birleştir; orijinaller değişmez.'),
('cropVideo','Crop video','Video alanını kırp','Select a region directly on the video preview. Drag, resize, use Shift ratio lock and Return to export.','Video önizlemesinde alan seç. Sürükle, boyutlandır; Shift ile oranı kilitle, Enter ile kopyayı dışa aktar.'),
('changeVideoSpeed','Change speed','Video hızını değiştir','Change video speed with matching audio tempo and preview controls.','Önizleme kontrolleriyle video hızını ve buna eşlik eden ses temposunu değiştir.'),
('joinVideos','Join videos','Videoları birleştir','Join multiple clips in order, adapting geometry, frame rate and audio layout to a consistent output.','Klipleri sırayla birleştir; boyut, kare hızı ve ses düzeni tutarlı bir çıktıya uyarlanır.'),
('videoSnapshots','Video snapshots','Videodan kare al','Choose timestamps and save still frames as new PNG files.','Zaman noktalarını seçip kareleri yeni PNG dosyaları olarak kaydet.'),
('splitVideo','Split video','Video böl','Split at markers, equal clip counts or intervals. Remove unwanted segments; save separately or join retained clips.','İşaretlerden, eşit klip sayısından veya aralıklardan böl. İstenmeyen parçaları çıkar; kalanları ayrı veya birleşik kaydet.'),
('audioToVideo','Audio to video','Sesten video','Create a waveform, spectrum, frequency-bar or still-image video from an audio file.','Ses dosyasından waveform, spektrum, frekans çubukları veya sabit görselle video oluştur.'),
('trimAudio','Trim audio','Ses kırp','Waveform preview, In/Out handles and selected-range playback. Optional silence trimming and keyboard seeking.','Waveform önizleme, In/Out tutamaçları ve seçili aralığı oynatma. İsteğe bağlı sessizlik kesme ve klavyeyle gezinme.'),
('audioChannels','Audio channels','Ses kanalları','Convert mono/stereo and set left/right levels, with channel previews.','Mono/stereo dönüşümü yap, sol/sağ seviyelerini ayarla ve kanalları önizle.'),
('createCollage','Create collage','Kolaj oluştur','Arrange several images in a configurable layout with gaps and background styling.','Birden fazla görseli aralık ve arka plan ayarlarıyla düzenlenebilir bir kolajda birleştir.'),
('redactImage','Redact image','Görselde gizle','Select areas and export with solid, blur or pixelation treatments. Always verify the resulting file before sharing.','Alan seçip düz renk, blur veya pikselleştirme uygula. Paylaşmadan önce çıktıyı kontrol et.'),
('redactVideo','Redact video','Videoda gizle','Define rectangular regions and time ranges for solid, blur or pixelated redaction.','Düz renk, blur veya pikselleştirme için dikdörtgen alanlar ve zaman aralıkları seç.'),
('redactAudio','Redact audio','Seste gizle','Choose intervals to replace with a bleep or silence; preserve the rest of the audio.','Bleep veya sessizlikle değiştirilecek aralıkları seç; sesin geri kalanı korunur.'),
('readQRCode','Read QR codes','QR kod oku','Scan supported images and PDF pages, review detected contents and export a report.','Desteklenen görsel ve PDF sayfalarını tara; bulunan içerikleri inceleyip rapor dışa aktar.')]
assert set(x[0] for x in features)==set(catalog['tools'])
shortcuts=[('⇧ + drag','Convert wheel','Dönüştürme çarkı'),('⌘ + drag','Tools wheel','Araç çarkı'),('⌃ + drag','File actions wheel','Dosya işlemleri çarkı'),('⌃ ⇧ D','Download a copied web link','Kopyalanmış web linkini indir'),('← ↑ / → ↓','Previous / next wheel item','Önceki / sonraki çark öğesi'),('Home / End','First / last wheel item','İlk / son çark öğesi'),('Enter / Space','Choose highlighted wheel item','Çarktaki seçili öğeyi uygula'),('Esc / Tab','Close wheel','Çarkı kapat'),('Space','Play / pause in supported media editors','Medya editörlerinde oynat / duraklat'),('← / →','Seek backward / forward 1 second','1 saniye geri / ileri git'),('⇧ ← / ⇧ →','Video: 1 frame; audio: 0.1 second','Video: 1 kare; ses: 0,1 saniye'),('I / O','Set selection In / Out','Seçimin In / Out noktasını belirle'),('⇧ Space','Play the selected range','Seçili aralığı oynat'),('M','Add a split marker where supported','Desteklenen araçlarda bölme işareti ekle'),('Home / End','Go to beginning / end of preview','Önizlemenin başına / sonuna git'),('⇧ + crop drag','Lock crop aspect ratio','Crop en-boy oranını kilitle'),('Enter','Export crop in the crop editor','Crop editöründe kırpılmış kopyayı kaydet'),('⌘ S','Save from supported editors','Desteklenen editörlerde kaydet'),('⌘ ,','Open settings','Ayarları aç'),('⌘ Q','Quit Nashi','Nashi’den çık')]
E=html.escape
for language in ['en','tr']:
 tr=language=='tr';prefix='../' if tr else '';assets=prefix+'assets/';choose=lambda en,tt:tt if tr else en
 title=choose('Your files,<br>a little sweeter.','Dosyaların için<br>tatlı bir kolaylık.')
 cards=''.join(f'<article class="tool"><span class="tool-number">{i+1:02}</span><h3>{E(x[2] if tr else x[1])}</h3><p>{E(x[4] if tr else x[3])}</p></article>' for i,x in enumerate(features))
 table=''.join('<tr><th scope="row">'+E(ext.upper())+'</th><td>'+', '.join(E(x.upper()) for x in dest)+'</td></tr>' for ext,dest in catalog['conversionMatrix'].items())
 keys=''.join(f'<tr><th scope="row"><kbd>{E(key)}</kbd></th><td>{E(tt if tr else en)}</td></tr>' for key,en,tt in shortcuts)
 doc=f'''<!doctype html>
<html lang="{language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self'; style-src 'self'; script-src 'self'; connect-src 'none'; base-uri 'none'; form-action 'none'">
<meta name="description" content="{choose('Nashi: open-source local file conversion, editing, web downloads and a playful drag wheel. All features, formats and keyboard shortcuts.','Nashi: açık kaynaklı yerel dosya dönüştürme, düzenleme, web indirme ve sürükleme çarkı. Tüm özellikler, formatlar ve kısayollar.')}">
<title>Nashi — {choose('Your files, a little sweeter','Dosyaların için tatlı bir kolaylık')}</title><link rel="icon" href="{assets}nashi.png"><link rel="stylesheet" href="{assets}site.css"><script src="{assets}site.js" defer></script></head>
<body><a class="skip" href="#main">{choose('Skip to content','İçeriğe geç')}</a><header><a class="brand" href="#"><img src="{assets}nashi.png" alt="" width="42" height="42">Nashi</a><nav aria-label="{choose('Main navigation','Ana gezinme')}"><a href="#features">{choose('Features','Özellikler')}</a><a href="#formats">{choose('Formats','Formatlar')}</a><a href="#shortcuts">{choose('Shortcuts','Kısayollar')}</a><a href="{('../index.html' if tr else 'tr/index.html')}">{'EN' if tr else 'TR'}</a><a class="nav-github" href="https://github.com/orkunisitmak/nashi-app">GitHub ↗</a></nav></header>
<main id="main"><section class="hero"><div><span class="eyebrow">{choose('A little less file fuss','Dosyalarla daha az uğraş')}</span><h1>{title}</h1><p class="intro">{choose('Convert, fine-tune and send them on their way. A small, friendly toolbox for the files you use every day.','Dönüştür, düzenle ve yoluna gönder. Her gün kullandığın dosyalar için küçük, samimi bir araç kutusu.')}</p><div class="hero-actions"><a class="button primary" href="#download">{choose('Get Nashi','Nashi’yi edin')} ↗</a><a class="button secondary" href="#features">{choose('Explore the toolbox','Araçları keşfet')} ↓</a></div><p class="subtle">MIT · {choose('Local processing · No subscription','Yerel işlem · Abonelik yok')}</p></div><div class="illustration" aria-label="{choose('Illustration of the drag wheel','Sürükleme çarkı illüstrasyonu')}"><div class="file float-a">▧ <span>photo.png</span></div><div class="file float-b">♫ <span>sound.wav</span></div><div class="wheel"><span class="petal p1">{choose('CONVERT','DÖNÜŞTÜR')}</span><span class="petal p2">{choose('EDIT','DÜZENLE')}</span><span class="petal p3">{choose('SHARE','PAYLAŞ')}</span><span class="petal p4">{choose('DOWNLOAD','İNDİR')}</span><div class="wheel-center"><img src="{assets}nashi.png" width="92" height="92" alt="Nashi"></div></div><div class="done">✓ {choose('Nicely done. A fresh file is ready.','Tamamdır. Yeni dosyan hazır.')}</div></div></section>
<section class="status" id="download"><div><span class="eyebrow">{choose('Release preparation','Yayın hazırlığı')}</span><h2>{choose('Built to be yours.','Senin kullanımın için.')}</h2><p>{choose('Public packages and the Windows port are being verified. Official download links will appear here and in GitHub Releases when ready.','Public paketler ve Windows portu doğrulanıyor. Hazır olduklarında resmi indirme linkleri burada ve GitHub Releases bölümünde yer alacak.')}</p></div><div class="platforms"><div><strong>macOS</strong><span>Apple Silicon · macOS 13+</span><span class="pill">{choose('Source available','Kaynak kod hazır')}</span></div><div><strong>Windows</strong><span>x64 · {choose('Native port','Yerel uygulama portu')}</span><span class="pill muted">{choose('In development','Geliştiriliyor')}</span></div><a class="button secondary" href="https://github.com/orkunisitmak/nashi-app/releases">{choose('View releases','Yayınları görüntüle')} ↗</a></div></section>
<section class="flow"><div class="section-heading"><span class="eyebrow">{choose('The everyday flow','Günlük kullanım')}</span><h2>{choose('One gesture. Many possibilities.','Tek hareket. Bir sürü olasılık.')}</h2></div><div class="flow-grid"><article><b>01</b><h3>{choose('Choose or drag','Seç veya sürükle')}</h3><p>{choose('Use Home or drag a file in Finder and hold Shift, Command or Control to open the matching wheel.','Ana ekrandan dosya seç veya Finder’da dosyayı sürüklerken Shift, Command ya da Control basılı tut.')}</p></article><article><b>02</b><h3>{choose('Make it yours','İstediğin hale getir')}</h3><p>{choose('Choose a format or tool. Preview edits and use keyboard controls for precise adjustments.','Formatı veya aracı seç. Düzenlemeyi önizle; hassas ayarlar için klavyeyi kullan.')}</p></article><article><b>03</b><h3>{choose('Save a fresh copy','Yeni kopyayı kaydet')}</h3><p>{choose('Watch real progress and save a new output. A short, borderless success card shows when it is ready.','Gerçek ilerlemeyi izle ve yeni çıktıyı kaydet. Tamamlandığında kısa, çerçevesiz bir bildirim görünür.')}</p></article></div></section>
<section id="features"><div class="section-heading"><span class="eyebrow">{choose('The macOS toolbox','macOS araç kutusu')}</span><h2>27 {choose('tools. Room to create.','araç. Üretmek için alan.')}</h2><p>{choose('The complete current macOS tool catalog. Windows availability will be identified separately as its port is verified.','Mevcut macOS sürümünün tam araç kataloğu. Windows araçlarının kullanılabilirliği port doğrulandıkça ayrıca belirtilecek.')}</p></div><div class="tool-grid">{cards}</div></section>
<section class="web-feature"><span class="eyebrow">{choose('From the web to your workflow','Web’den iş akışına')}</span><h2>{choose('A link. A file. Yours to work with.','Bir link. Bir dosya. İşlemek sana kalmış.')}</h2><p>{choose('Paste a public video share link or direct media address. Choose video, MP3 or the original image/media, quality and destination. YouTube cards can offer video and thumbnail separately; Instagram reel cards need an actual reel link.','Public video paylaşım linkini veya doğrudan medya adresini yapıştır. Video, MP3 ya da orijinal görsel/medyayı; kaliteyi ve klasörü seç. YouTube kartlarında video ve thumbnail ayrı sunulabilir; Instagram reel kartlarında gerçek reel linki gerekir.')}</p><p>{choose('Use Control–Shift–D for a copied link, drag a browser card with Command, or drop it onto Home. Some players only expose a poster or blob address; Copy Share Link is the fallback. Supported sites change. DRM, live streams, login-required media, bulk galleries and playlists are not supported in this release.','Kopyalanmış link için Control–Shift–D kullan; tarayıcı kartını Command ile sürükle veya Ana ekrana bırak. Bazı oynatıcılar yalnızca poster/blob adresi verir; bu durumda paylaşım linkini kopyala. Site desteği değişebilir. Bu sürümde DRM, canlı yayın, giriş gerektiren medya, toplu galeriler ve playlistler desteklenmez.')}</p></section>
<section id="formats"><div class="section-heading"><span class="eyebrow">{choose('Formats, without the guesswork','Formatları açıkça gör')}</span><h2>45 {choose('inputs.','girdi.')} 275 {choose('routes.','dönüşüm yolu.')}</h2><p>{choose('This table is generated from the app catalog. A format appearing here does not mean every advanced document feature can be retained. PDF to DOCX/XLSX reconstruction is heuristic; PDF to PPTX uses page images.','Bu tablo uygulama kataloğundan üretilir. Bir formatın listelenmesi, her gelişmiş belge özelliğinin korunabildiği anlamına gelmez. PDF→DOCX/XLSX yeniden kurma sezgiseldir; PDF→PPTX sayfa görselleri kullanır.')}</p></div><label class="search-label" for="format-search">{choose('Find an input or output format','Girdi veya çıktı formatı ara')}</label><input id="format-search" type="search" placeholder="PNG, MP4, PDF…" autocomplete="off"><div class="table-wrap"><table id="format-table"><thead><tr><th>{choose('Input','Girdi')}</th><th>{choose('Available outputs','Çıktılar')}</th></tr></thead><tbody>{table}</tbody></table></div></section>
<section class="actions"><h2>{choose('Six ways to keep files moving.','Dosyaları ilerletmenin altı yolu.')}</h2><div class="action-list">{''.join('<span>'+E(v)+'</span>' for v in (['AirDrop','Float','Copy','Move','Copy path','Open in Terminal'] if not tr else ['AirDrop','Float rafı','Kopyala','Taşı','Yolu kopyala','Terminal’de aç']))}</div><p>{choose('Float keeps files in a small shelf. History can be searched, reused and revealed in Finder. Move explicitly moves originals; exports create new copies and do not overwrite existing names.','Float dosyaları küçük bir rafta tutar. Geçmişte ara, dosyaları yeniden kullan veya Finder’da göster. Taşı işlemi orijinali taşır; dışa aktarımlar yeni kopya oluşturur ve mevcut adların üzerine yazmaz.')}</p></section>
<section id="shortcuts"><div class="section-heading"><span class="eyebrow">{choose('Keep your hands in flow','Elin alışsın, işin hızlansın')}</span><h2>{choose('The shortcut sheet.','Kısayol rehberi.')}</h2><p>{choose('macOS defaults. Drag modifiers are customizable. Editor shortcuts apply where that action is available; text fields and native controls retain their normal input behavior.','macOS varsayılanları. Sürükleme tuşları özelleştirilebilir. Editör kısayolları ilgili işlem destekleniyorsa çalışır; metin alanları ve yerel kontroller normal davranışını korur.')}</p></div><div class="table-wrap"><table><thead><tr><th>{choose('Shortcut','Kısayol')}</th><th>{choose('Action','İşlem')}</th></tr></thead><tbody>{keys}</tbody></table></div></section>
<section class="trust"><div><span class="eyebrow">{choose('Local first. Open by design.','Önce yerel. Tasarımı açık.')}</span><h2>{choose('Small footprint.<br>Clear boundaries.','Küçük araç.<br>Açık sınırlar.')}</h2></div><div><h3>{choose('Privacy','Gizlilik')}</h3><p>{choose('Conversion and editing run locally. Web downloads contact the chosen site. No analytics, cloud account, browser-cookie import or subscription is built in.','Dönüştürme ve düzenleme yerelde çalışır. Web indirmeleri seçilen siteye bağlanır. Analytics, bulut hesabı, tarayıcı çerezi aktarma veya abonelik bulunmaz.')}</p><h3>{choose('Signed updates','İmzalı güncellemeler')}</h3><p>{choose('Official public updates require no GitHub token. Feeds and downloads are verified with a pinned signing key; active jobs finish before the app restarts.','Resmi public güncellemeler GitHub tokenı istemez. Feed ve indirmeler sabit imza anahtarıyla doğrulanır; yeniden başlatmadan önce mevcut iş tamamlanır.')}</p><h3>{choose('Transparent limitations','Açık sınırlamalar')}</h3><p>{choose('Complex document conversions are best-effort. Haptic feedback depends on hardware. macOS and Windows may show first-run warnings for builds without an OS-trusted publisher signature. We do not ask you to disable system security.','Karmaşık belge dönüşümleri her özelliği koruyamayabilir. Titreşim donanıma bağlıdır. İşletim sistemince güvenilen yayıncı imzası olmayan build’lerde macOS/Windows ilk açılış uyarıları gösterebilir. Sistem güvenliğini kapatmanız istenmez.')}</p></div></section>
<section class="inspiration"><h2>{choose('Inspired. Independently made.','İlham alındı. Bağımsız geliştirildi.')}</h2><p>{choose('Nashi was inspired by Tangerine’s delightful drag-and-wheel interaction and adds new features and refined workflows. It is not affiliated with or endorsed by Tangerine or LEAP STUDIO.','Nashi, Tangerine’in keyifli sürükle ve çark etkileşiminden ilham aldı; yeni özellikler ve geliştirilmiş iş akışları ekliyor. Tangerine veya LEAP STUDIO ile bağlantılı değildir ve onlar tarafından desteklenmez.')}</p><a href="https://tangerineformac.com/">Tangerine ↗</a></section></main>
<footer><a class="brand" href="#">Nashi <span>◉</span></a><p>{choose('Original source under MIT. Third-party tools keep their own licenses.','Orijinal kaynak kod MIT lisanslıdır. Üçüncü taraf araçların kendi lisansları geçerlidir.')}</p><a href="https://github.com/orkunisitmak/nashi-app/blob/main/SECURITY.md">{choose('Security','Güvenlik')}</a><a href="https://github.com/orkunisitmak/nashi-app/blob/main/LICENSE">MIT</a></footer></body></html>'''
 out=R/'docs'/('tr/index.html' if tr else 'index.html');out.write_text(doc)
print('Built EN/TR pages: 27 tools, 45 inputs, 275 routes,',len(shortcuts),'shortcuts each')
